"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["52170"],{74625(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.fase_cronograma.pendencia_reenvio_exige_complementacao","status":422,"titulo":"A fase n\xe3o pode perder PermiteComplementacao \u2014 \xe9 referenciada por documento exigido com consequ\xeancia ABRE_PRAZO_PARA_REENVIO"},"descricao":{"codigo":"uniplus.selecao.fase_cronograma.pendencia_reenvio_exige_complementacao","requisitos":["UNI-REQ-0070"],"oQueAconteceu":["A consequ\xeancia `ABRE_PRAZO_PARA_REENVIO` de um documento exigido, ou de um grupo de\\nalternativas (OU), s\xf3 faz sentido numa fase que permite complementa\xe7\xe3o de\\ndocumentos. A fase j\xe1 estava no cronograma do processo com a permiss\xe3o de\\ncomplementar, e a defini\xe7\xe3o do cronograma a deixaria sem ela, mas ainda h\xe1, nessa\\nfase, exig\xeancia com essa consequ\xeancia. A mensagem traz o c\xf3digo da fase e a\\nordem dela.","A permiss\xe3o de complementar n\xe3o \xe9 digitada no pedido: a cada defini\xe7\xe3o do\\ncronograma ela \xe9 copiada da fase can\xf4nica do cadastro do m\xf3dulo Configura\xe7\xe3o. A\\nrecusa aparece, portanto, quando o cadastro deixou de permitir a complementa\xe7\xe3o\\nnessa fase depois de o processo ter gravado a exig\xeancia. \xc9 o lado \\"de volta\\" da\\nconfer\xeancia feita ao gravar a exig\xeancia\\n([`uniplus.selecao.documento_exigido.pendencia_reenvio_exige_complementacao`](/erros/uniplus.selecao.documento_exigido.pendencia_reenvio_exige_complementacao)).","A confer\xeancia \xe9 feita fase por fase, na ordem em que o processo as tem, e para na\\nprimeira recusa. Para a fase mantida, esta vem antes da confer\xeancia do extremo do\\nper\xedodo usado como refer\xeancia de idade m\xe1xima de emiss\xe3o. Nada \xe9 gravado."],"comoResolver":["Troque a consequ\xeancia das exig\xeancias da fase por outra das previstas, nos\\ndocumentos e nos grupos que a declaram (defini\xe7\xe3o de documentos exigidos), ou\\nmude-as para uma fase que permite complementa\xe7\xe3o, e repita a defini\xe7\xe3o do\\ncronograma. Se a fase deve continuar permitindo a complementa\xe7\xe3o, o ajuste \xe9 no\\ncadastro de fases can\xf4nicas, feito por quem o gere."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Fase cronograma"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);